;// CONCATENATED MODULE: ./node_modules/probot/lib/server/handlers/static-files.js



const staticFilesHandler = (req, res) => {
    if (req.method === "GET") {
        const path = req.url?.split("?")[0] || "";
        if (path === "/probot/static/robot.svg") {
            res
                .writeHead(200, {
                "cache-control": "max-age=86400",
                "content-type": "image/svg+xml",
            })
                .end(robot_svg);
            return true;
        }
        if (path === "/probot/static/probot-head.svg") {
            res
                .writeHead(200, {
                "cache-control": "max-age=86400",
                "content-type": "image/svg+xml",
            })
                .end(probot_head_svg);
            return true;
        }
        if (path === "/probot/static/primer.css") {
            res
                .writeHead(200, {
                "cache-control": "max-age=86400",
                "content-type": "text/css",
            })
                .end(primer_css);
            return true;
        }
    }
    return false;
};

